"use strict";(self.webpackChunkwiki_pt_br=self.webpackChunkwiki_pt_br||[]).push([["43909"],{38716(e){e.exports=JSON.parse('{"tag":{"label":"reComputer Robotics","permalink":"/pt-br/tags/re-computer-robotics","allTagsPath":"/pt-br/tags","count":2,"items":[{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/pt_reComputer_Robotics_Hardware_Interfaces_Usage","title":"Hardware e Uso de Interfaces da reComputer Robotics","description":"Este wiki fornece uma introdu\xe7\xe3o abrangente aos recursos de hardware e ao uso das interfaces da placa carrier reComputer Jetson Robotics J401. Ele abrange especifica\xe7\xf5es detalhadas, m\xf3dulos suportados, instru\xe7\xf5es de configura\xe7\xe3o e guias pr\xe1ticos para usar v\xe1rias interfaces, como expans\xe3o de c\xe2mera M.2, Ethernet, USB, CAN, UART, I2C e GMSL2, ajudando os usu\xe1rios a iniciar rapidamente o desenvolvimento em rob\xf3tica na plataforma J401.","permalink":"/pt-br/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/pt_reComputer_Robotics_Getting_Started","title":"Introdu\xe7\xe3o ao reComputer Robotics","description":"A reComputer Robotics J401 \xe9 uma placa carrier de borda de IA de alto desempenho projetada para aplica\xe7\xf5es avan\xe7adas de rob\xf3tica. Ela suporta m\xf3dulos NVIDIA Jetson Orin Nano e Orin NX nos modos Super/MAXN, oferecendo at\xe9 157 TOPS de poder de computa\xe7\xe3o de IA. A placa oferece amplas op\xe7\xf5es de conectividade, incluindo Ethernet Gigabit dupla, m\xfaltiplas portas USB 3.2, CAN, slots M.2 para m\xf3dulos 5G/Wi-Fi/BT e suporte opcional a c\xe2mera GMSL2. Pr\xe9-instalada com JetPack 6, garante uma implanta\xe7\xe3o perfeita para desenvolvimento em rob\xf3tica. O design robusto suporta ampla faixa de temperatura de opera\xe7\xe3o e inclui um dissipador de calor com ventilador pr\xe9-instalado. A configura\xe7\xe3o envolve gravar o sistema operacional JetPack em um SSD NVMe usando um PC host Ubuntu compat\xedvel, seguida de configura\xe7\xe3o de hardware e uso das interfaces. Especifica\xe7\xf5es detalhadas de hardware, desenhos mec\xe2nicos e recursos t\xe9cnicos s\xe3o fornecidos para desenvolvedores, juntamente com canais de suporte t\xe9cnico e comunidade para solu\xe7\xe3o de problemas e discuss\xe3o.","permalink":"/pt-br/recomputer_robotics_j401_getting_started"}],"unlisted":false}}')}}]);